//! The published Codewire workspace image.
//!
//! `pin.rs` is the one place its digest is written. It is generated by
//! `scripts/ci/images/workspace-image-pin.py`: after support-images.yaml
//! publishes an image from main, a proposal rewrites the pin, and repository
//! policy refuses a workspace digest copied anywhere else. A deployment pulls
//! the digest from the repository it configures
//! (`CODEWIRE_WORKSPACE_IMAGE_REPOSITORY`, see docs/CONFIGURATION.md); local
//! environments pull it anonymously as [`PUBLIC_IMAGE`].

mod pin;

pub use pin::{
    AGENT_VERSIONS, DIGEST, INPUTS_SHA256, PLATFORMS, PREVIOUS_DIGESTS, PUBLIC_IMAGE, SOURCE_SHA,
};

/// Public mirror of the published manifests.
pub const PUBLIC_REPOSITORY: &str = "ghcr.io/codewiresh/workspace";

/// The pinned digest at `repository`.
pub fn image_at(repository: &str) -> String {
    format!("{repository}@{DIGEST}")
}

/// The version of `agent` that the pinned image installs, as its package
/// names it, such as `2.1.288` for `claude`. Checks of the running image read
/// it here, so they move with the pin and never ahead of it.
pub fn agent_version(agent: &str) -> Option<&'static str> {
    AGENT_VERSIONS
        .iter()
        .find(|(name, _)| *name == agent)
        .map(|(_, version)| *version)
}

/// Whether `image_ref` names the canonical workspace: the current digest, or
/// one an older client still sends, at the deployment's `repository` or at
/// the public mirror.
pub fn is_canonical(image_ref: &str, repository: &str) -> bool {
    let Some((named, digest)) = image_ref.trim().split_once('@') else {
        return false;
    };
    (named == repository || named == PUBLIC_REPOSITORY)
        && (digest == DIGEST || PREVIOUS_DIGESTS.contains(&digest))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn exact_digest(digest: &str) -> bool {
        digest.strip_prefix("sha256:").is_some_and(|hex| {
            hex.len() == 64
                && hex
                    .bytes()
                    .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase())
        })
    }

    /// A deployment's own repository, as docs/CONFIGURATION.md's example
    /// names it.
    const REPOSITORY: &str = "registry.example.invalid/codewire/workspace";

    #[test]
    fn pin_names_one_digest_at_the_public_mirror() {
        assert!(exact_digest(DIGEST));
        assert_eq!(PUBLIC_IMAGE, image_at(PUBLIC_REPOSITORY));
        assert_eq!(image_at(REPOSITORY), format!("{REPOSITORY}@{DIGEST}"));
        assert_eq!(SOURCE_SHA.len(), 40);
        assert_eq!(INPUTS_SHA256.len(), 64);
        for digest in PREVIOUS_DIGESTS {
            assert!(exact_digest(digest), "{digest}");
            assert_ne!(*digest, DIGEST);
        }
        let agents: Vec<&str> = AGENT_VERSIONS.iter().map(|(name, _)| *name).collect();
        assert_eq!(agents, ["claude", "codex", "gemini", "kimi", "pi"]);
        for (name, version) in AGENT_VERSIONS {
            assert_eq!(agent_version(name), Some(*version));
        }
        assert_eq!(agent_version("aider"), None);
    }

    #[test]
    fn the_pinned_image_serves_amd64_and_known_platforms_in_order() {
        assert!(PLATFORMS.contains(&"linux/amd64"));
        let known = ["linux/amd64", "linux/arm64"];
        let ordered: Vec<&str> = known
            .into_iter()
            .filter(|platform| PLATFORMS.contains(platform))
            .collect();
        assert_eq!(PLATFORMS, ordered.as_slice());
    }

    #[test]
    fn canonical_references_are_exact_current_or_previous_digests() {
        assert!(is_canonical(&image_at(REPOSITORY), REPOSITORY));
        assert!(is_canonical(PUBLIC_IMAGE, REPOSITORY));
        assert!(is_canonical(&format!(" {PUBLIC_IMAGE} "), REPOSITORY));
        for digest in PREVIOUS_DIGESTS {
            assert!(is_canonical(
                &format!("{PUBLIC_REPOSITORY}@{digest}"),
                REPOSITORY
            ));
            assert!(is_canonical(&format!("{REPOSITORY}@{digest}"), REPOSITORY));
        }
        let other = format!("sha256:{}", "e".repeat(64));
        for refused in [
            format!("{PUBLIC_REPOSITORY}@{other}"),
            format!("ghcr.io/acme/workspace@{DIGEST}"),
            format!("registry.example.invalid/other/workspace@{DIGEST}"),
            format!("{PUBLIC_REPOSITORY}:latest"),
            PUBLIC_REPOSITORY.to_string(),
            String::new(),
        ] {
            assert!(!is_canonical(&refused, REPOSITORY), "{refused}");
        }
    }
}
